import { ENVIRONMENTS, type Environment, ID_PATTERNS } from "@antireverse/protocol";
import type { NextRequest } from "next/server";
import { fetchAppSetup } from "@/lib/api.ts";
import { SESSION_COOKIE } from "@/lib/session.ts";

// The set-up proxy (slice 16): the Set up page polls it every 5 s while Guard or Harden is not done yet. No segment
// config is exported. The route types of `.next/types` are generated by `next typegen`, which this slice does not
// run, so the context is written out.

interface SetupRouteContext {
  params: Promise<{ appId: string }>;
}

function problem(status: number, title: string): Response {
  return new Response(JSON.stringify({ type: "about:blank", title, status }), {
    status,
    headers: { "content-type": "application/problem+json", "cache-control": "no-store" },
  });
}

const isEnvironment = (value: string): value is Environment => (ENVIRONMENTS as readonly string[]).includes(value);

export async function GET(request: NextRequest, context: SetupRouteContext): Promise<Response> {
  // Checked before anything else: a value that is not an App identifier never becomes part of an upstream URL.
  const { appId } = await context.params;
  if (!ID_PATTERNS.app.test(appId)) return problem(404, "Not Found");
  const asked = request.nextUrl.searchParams.get("environment");
  if (asked !== null && !isEnvironment(asked)) return problem(400, "Bad Request");

  const key = request.cookies.get(SESSION_COOKIE)?.value;
  if (!key) return problem(401, "Unauthorized");

  let upstream: Response;
  try {
    upstream = await fetchAppSetup(key, appId, asked ?? undefined, request.signal);
  } catch {
    // The error is not forwarded: a transport error may quote the request it could not send.
    return problem(502, "The Airverse API could not be reached");
  }

  return new Response(upstream.body, {
    status: upstream.status,
    headers: {
      "content-type": upstream.headers.get("content-type") ?? "application/octet-stream",
      "cache-control": "no-store",
    },
  });
}
